function sumPathNumbers(root: TreeNode | null): number {
  const walk = (node: TreeNode | null, value: number): number => {
    if (!node) return 0;
    value = value * 2 + node.val;
    if (!node.left && !node.right) return value;
    return walk(node.left, value) + walk(node.right, value);
  };
  return walk(root, 0);
}

