function sumPathNumbers(root: TreeNode | null): number {
  if (!root) return 0;
  let total = 0;
  const stack: [TreeNode, number][] = [[root, 0]];
  while (stack.length) {
    const [node, before] = stack.pop()!;
    const value = before * 2 + node.val;
    if (!node.left && !node.right) total += value;
    if (node.right) stack.push([node.right, value]);
    if (node.left) stack.push([node.left, value]);
  }
  return total;
}

